// Constant objects in the namespace idiom: function tables called through a
// computed key, primitive members, a constructor function, and the forms
// that must keep their dynamic reads.
var lib = lib || {};

// Primitive members written in the literal itself.
lib.Mode = { OFF: 0, ON: 1, LABEL: "mode", NEG: -2 };
lib.describe = function (m) {
  return m === lib.Mode.ON ? lib.Mode.LABEL + ":on" : lib.Mode.LABEL + ":off";
};

// A table of functions that do not use `this`, called with a string key.
lib.ops = {
  add: function (a, b) {
    return a + b;
  },
  mul: function (a, b) {
    return a * b;
  },
  sub: function (a, b) {
    return a - b;
  },
};
lib.apply = function (op, a, b) {
  return lib.ops[op](a, b);
};

// A member that reads `this`: the call keeps its receiver.
lib.counter = {
  base: 10,
  get: function () {
    return this.base;
  },
};
lib.read = function (k) {
  return lib.counter[k]();
};

// A table written after initialization.
lib.handlers = {
  a: function () {
    return "a";
  },
};
lib.register = function (name, fn) {
  lib.handlers[name] = fn;
};
lib.dispatch = function (name) {
  return lib.handlers[name]();
};

// A table called with number keys.
lib.byIndex = {
  0: function () {
    return "zero";
  },
  1: function () {
    return "one";
  },
};
lib.pick = function (i) {
  return lib.byIndex[i]();
};

// A primitive member written after initialization.
lib.Limits = { MAX: 5 };
lib.bump = function () {
  lib.Limits.MAX = 6;
};
lib.limit = function () {
  return lib.Limits.MAX;
};

// A constructor function with prototype methods.
lib.Pair = function (a, b) {
  this.a = a;
  this.b = b;
};
lib.Pair.prototype.sum = function () {
  return this.a + this.b;
};

module.exports = { lib };
